function enhanceHydroAudit(){let view=q('[data-view="hydro-inverse"]'),explorer=q('#hydroSimulationExplorer');if(!view||!explorer)return;let audit=q('#v22HydroSearch');if(!audit){audit=document.createElement('section');audit.id='v22HydroSearch';audit.className='section card pad v22-hydro-audit';explorer.before(audit)}audit.innerHTML=`<h2>What was inverted—and what was not</h2><p>The target is the Glint-ACOLITE-corrected B02/B03/B04 spectrum. This is acceptable for asking whether a plausible HydroLight scenario can reproduce the correction, but it is <b>not independent validation</b>. The word “selected” means the smallest mismatch inside the tested library, not measured Tidung TSM.</p><div class="table-wrap"><table><thead><tr><th>Model input</th><th>Values searched or fixed</th><th>Meaning</th></tr></thead><tbody><tr><th>Scene geometry</th><td>SZA grid 20°, 25°, 30°, 35°, 40°</td><td>Nearest SZA is fixed first; the scene’s Sentinel-2A/2B/2C spectral response is used.</td></tr><tr><th>Optical background</th><td>OLI: Chl-a 0.05, CDOM 0.01<br>CLR: Chl-a 0.10, CDOM 0.03<br>PRD: Chl-a 0.50, CDOM 0.06</td><td>All three paired Chl/CDOM scenarios are tested. Chl and CDOM were <b>not independently optimized</b>.</td></tr><tr><th>TSM</th><td>15 discrete values from 0.1 to 80 g m⁻³, including 0.5 and 1</td><td>TSM is varied within each background. The result is a grid choice, not a continuous laboratory measurement.</td></tr><tr><th>Fixed assumptions</th><td>Wind 5 m s⁻¹; optically deep water; no bottom</td><td>These were not fitted. Wrong fixed assumptions can move the apparent best TSM.</td></tr></tbody></table></div><div class="v22-search-rule"><b>Automatic rule:</b> choose nearest SZA, then compare 3 backgrounds × 15 TSM = 45 spectra using B02/B03/B04 RMSE. The smallest RMSE is the discrete best match. The 0.5–1 g m⁻³ sensitivity panel below deliberately shows both professor-suggested values and all three background scenarios so the conclusion does not depend on only one curve.</div>`;let row=q('.select-row',explorer),sceneSelect=q('#v23HydroScene');if(!sceneSelect){let label=document.createElement('label');label.innerHTML='<span>Sentinel-2 scene</span><select id="v23HydroScene"></select>';row.prepend(label);sceneSelect=q('#v23HydroScene')}let eligibleScenes=[...new Set(V20.inverseRows.filter(x=>x.roi==='C1').map(x=>x.scene))];sceneSelect.innerHTML=eligibleScenes.map(id=>{let s=DATA.scenes.find(x=>x.scene===id);return s?`<option value="${id}" ${id==='20241025_S2A'?'selected':''}>${sceneLabel(s)}</option>`:''}).join('');q('h2',explorer).textContent='Explore different dates and HydroLight assumptions';q('.lead',explorer).textContent='Choose a scene, satellite result, ROI, SZA, background and TSM. This manual viewer does not overwrite the stored inverse result.';qa('h3',explorer).forEach(h=>{if(/Selected simulation versus satellite method/i.test(h.textContent))h.textContent='Your manually selected simulation versus the satellite spectrum'});let result=q('#v22HydroSelectedReason');if(!result){result=document.createElement('section');result.id='v22HydroSelectedReason';result.className='v22-hydro-result';q('#hydroExplorerMetrics').insertAdjacentElement('afterend',result)};['v23HydroScene','hydroTargetMethod','hydroExplorerRoi','hydroExplorerSza','hydroExplorerBackground','hydroExplorerTsm'].forEach(id=>{let el=q('#'+id);if(el)el.onchange=()=>{if(id==='v23HydroScene'){let s=hydroExplorerScene(),vals=[...new Set(HYDRO_LUT_ROWS.filter(r=>r.platform===s.platform).map(r=>r.sza))],near=vals.reduce((a,b)=>Math.abs(b-s.diagnostics.geometry.sun_zenith_angle)<Math.abs(a-s.diagnostics.geometry.sun_zenith_angle)?b:a);q('#hydroExplorerSza').value=String(near)+'°'}renderHydroExplorerV23();setTimeout(installLargeViewers,0)}});renderHydroExplorerV23()}
