function setupFinalConclusion(){let view=q('[data-view="final"]');if(!view)return;q('#outputFolder')?.closest('section')?.remove();let oldMethod=q('#v31FinalMethod')?.value,rows=methodRows(),passing=rows.filter(r=>qcState(r).pass),defaultMethod=oldMethod||(passing.length===1?passing[0].key:'Adapted_ACOLITE'),host=q('#v21FinalWrap');if(!host){host=document.createElement('section');host.id='v21FinalWrap';host.className='section card pad';q('.hero',view)?.insertAdjacentElement('afterend',host)}host.innerHTML=`<div class="v21-final-head"><div><h2>Conclusion</h2><p>Select a date and correction method. Images, QC values and the HydroLight graph update together.</p></div><div class="v31-final-controls"><label>Date<select id="v21FinalScene">${DATA.scenes.map(s=>`<option value="${s.scene}" ${s.scene===current.scene?'selected':''}>${sceneLabel(s)}</option>`).join('')}</select></label><label>Correction shown<select id="v31FinalMethod"><option value="Adapted_ACOLITE">Glint-ACOLITE</option><option value="Hedley">Hedley</option><option value="NIR_SWIR_B12">B12 subtraction</option></select></label></div></div><div id="v24FinalPlain"></div><details class="v24-support"><summary>Detailed values for all three methods</summary><div id="v21FinalConclusion"></div></details><details class="v24-support"><summary>Overall results across all scenes</summary><section id="v22OverallSummary" class="v22-overall"></section></details><details class="v24-support"><summary>How the four checks are calculated</summary>${thresholdExplanation()}</details>`;q('#v31FinalMethod').value=defaultMethod;q('#v31FinalMethod').onchange=renderFinalPlainV24;q('#v21FinalScene').onchange=e=>{current=DATA.scenes.find(s=>s.scene===e.target.value);renderScene();setupHydroReference();setupFinalConclusion()};renderFinalPlainV24();renderMethodConclusion();renderOverallSummary()}
